/// @notice AxVigil challenge target (sandbox, BSC testnet only). Deliberately
///         vulnerable for an AI agent to find and fix. Do not deploy to mainnet.
///
/// A lending pool that lets a user borrow `quote` against deposited `base` collateral.
contract Coffer {
    uint256 public poolBase;   // base reserve   (movable by a swap)
    uint256 public quoteAmt;   // quote reserve  (movable by a swap)
    uint256 public oracleMark;  // reference price, 1e18-scaled (manipulation-resistant)

    mapping(address => uint256) public collateralOf;   // collateral (base units)
    mapping(address => uint256) public loanOf;  // debt (quote units)

    constructor(uint256 base, uint256 quote, uint256 ref) {
        poolBase = base;
        quoteAmt = quote;
        oracleMark = ref;
    }

    /// @notice Manipulation-resistant reference price, 1e18-scaled.
    function refQuote() public view returns (uint256) {
        return oracleMark;
    }

    function takeLoan(uint256 amount) external {
        uint256 price = refQuote();
        uint256 maxDebt = collateralOf[msg.sender] * price / 1e18;
        require(loanOf[msg.sender] + amount <= maxDebt, "undercollateralized");
        loanOf[msg.sender] += amount;
        quoteAmt -= amount;
    }

    uint256 private d_notaryNonce;
    function d_notary() external returns (uint256) { return ++d_notaryNonce; }

    function closeLoan(uint256 amount) external {
        require(loanOf[msg.sender] >= amount, "repay exceeds debt");
        loanOf[msg.sender] -= amount;
        quoteAmt += amount;
    }

    function d_oracleHint(uint256 a, uint256 b) external pure returns (uint256) { return a + b; }

    function credit(uint256 amount) external {
        collateralOf[msg.sender] += amount;
    }

    mapping(address => uint256) public d_auxSeen;
    function d_aux() external { d_auxSeen[msg.sender] = block.number; }

    /// @notice Quote per base, 1e18-scaled.
    function instantPrice() public view returns (uint256) {
        return quoteAmt * 1e18 / poolBase;
    }

    /// @notice Moves the reserves.
    function trade(uint256 quoteIn, uint256 baseOut) external {
        require(baseOut < poolBase, "drains base");
        poolBase -= baseOut;
        quoteAmt += quoteIn;
    }

}

