+        vm.stopPrank();
+
+        // victim deposits 1 ether
+        vm.startPrank(victim);
+        token.approve(address(reserve), type(uint256).max);
+        uint256 victimShares = reserve.credit(1 ether);
+        vm.stopPrank();
